    let m=read(format!("{Z}/docs/benchmarks/2026-10-27-clean-fft-adoption/artifacts/production-source-manifest.json"));for(f,h)in m["source_files_sha256"].as_object().unwrap(){let p=Path::new(Z).join(f);assert_eq!(hash(&p),h.as_str().unwrap());pin(&mut pins,p);}
    for f in["design.md","probe.rs","perf.rs","driver.rs","driver","native-flags.txt"]{pin(&mut pins,r(f));}pin(&mut pins,X);
